window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-de43d6fa1e379b2a"]={"versions": [{"id": "FIG-de43d6fa1e379b2a", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des internen Kontrollflusses der E2E-Protection-Wrapper-Funktion <code>E2EPW_Read_&lt;p&gt;_&lt;o&gt;</code> (E2EPW_Read1) innerhalb der AUTOSAR E2E Library. Der Wrapper fungiert als Bindeglied zwischen Software-Komponenten (SWC) und der AUTOSAR-RTE und stellt sicher, dass über die RTE empfangene Daten vor der weiteren Nutzung einer End-to-End-Schutzprüfung (E2E-Check) unterzogen werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Aufrufer:</strong> Software-Komponente (SWC), die Daten über die E2E-Wrapper-Funktion einliest.</li>\n<li><strong>Funktionsparameter / Variablen:</strong></li>\n<li><code>AppDataEl</code>: Zeiger auf den Puffer des Anwendungsdatenelements.</li>\n<li><code>retRteRead</code>: Lokale Variable für den Rückgabewert des RTE-Leseaufrufs.</li>\n<li><code>plausibilityChecks</code>: Statusvariable für Vorprüfungen und Deserialisierungsvalidierung.</li>\n<li><code>retE2ECheck</code>: Lokale Variable für den Rückgabewert der E2E-Prüfroutine.</li>\n<li><code>State</code> / <code>State1</code>: Zustandsstruktur des E2E-Profils (inkl. Flags <code>NewDataAvailable</code> und <code>Status</code>).</li>\n<li><code>Config1</code>: Konfigurationsstruktur für das spezifische E2E-Profil.</li>\n<li><code>Data</code>: Byte-Array bzw. I-PDU-Darstellung des Datenelements.</li>\n<li><code>ret</code>: 32-Bit-Zusammengesetzter Rückgabewert der Wrapper-Funktion.</li>\n<li><strong>Schnittstellen & externe Operationen:</strong></li>\n<li><code>Rte_Read_&lt;p&gt;_&lt;o&gt;(AppDataEl)</code>: RTE-Lese-API für Port <code>&lt;p&gt;</code> und Datenelement <code>&lt;o&gt;</code>.</li>\n<li><code>E2E_PXXCheck(Config1, State1, Data)</code>: Profilspezifische E2E-Prüffunktion der E2E-Library.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Start der Aktivität; Belegung von <code>retRteRead = RTE_E_OK</code>, <code>plausibilityChecks = E2E_E_OK</code> und <code>retE2ECheck = E2E_E_OK</code>.</li>\n<li><strong>Nullzeiger-Prüfung:</strong> Verzweigung über Guard <code>AppDataEl == NULL</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Setzen von <code>plausibilityChecks = E2E_E_INPUTERR_NULL</code>, Umgehung der Lese- und E2E-Prüfschritte zur Zusammenführung vor dem Rückgabewert.</li>\n<li><code>[FALSE]</code>: Ausführung von <code>rteRead = Rte_Read_&lt;p&gt;_&lt;o&gt;(AppDataEl)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Auswertung des RTE-Lesestatus:</strong> Verzweigung über Guard <code>retRteRead == RTE_E_OK</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Setzen von <code>State-&gt;NewDataAvailable = TRUE</code>.</li>\n<li><code>[FALSE]</code>: Setzen von <code>State-&gt;NewDataAvailable = FALSE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deserialisierungsprüfung:</strong> Nach der Zusammenführung erfolgt die Prüfung <code>Check deserialization of AppDataEl</code>. Verzweigung über Guard <code>Deserialization invalid?</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Setzen von <code>plausibilityChecks = E2EPW_E_DESERIALIZATION</code>.</li>\n<li><code>[FALSE]</code>: Serialisierung von <code>AppDataEl</code> in die I-PDU-Repräsentation <code>Data</code> (sofern es sich um ein komplexes Datenelement handelt) bzw. Kopieren in <code>Data</code> (falls Byte-Array). Anschließend Aufruf von <code>retE2ECheck = E2E_PXXCheck(Config1, State1, Data)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ergebnisbildung & Abschluss:</strong> Zusammenführung aller Pfade. Zusammensetzen des 32-Bit-Rückgabewerts per Bitschiebe- und ODER-Operation:</li>\n</ol>\n<p class=\"fig-p\"><code>ret = ( (retRteRead) | (retE2ECheck &lt;&lt; 8) | (plausibilityChecks &lt;&lt; 16) | (State1-&gt;Status &lt;&lt; 24) )</code>.</p>\n<p class=\"fig-p\">Rückgabe von <code>ret</code> und Übergang in den Endzustand.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Der Rückgabewert kodiert vier separate Statusbytes in einem einzigen 32-Bit-Wert: Byte 0 (Bits 0–7) enthält <code>retRteRead</code>, Byte 1 (Bits 8–15) <code>retE2ECheck</code>, Byte 2 (Bits 16–23) <code>plausibilityChecks</code> und Byte 3 (Bits 24–31) <code>State1-&gt;Status</code>.</li>\n<li>Wenn <code>AppDataEl</code> NULL ist oder die Deserialisierung fehlschlägt, wird der eigentliche E2E-Check (<code>E2E_PXXCheck</code>) übersprungen; Vorbelegungen (<code>E2E_E_OK</code>) bleiben für nicht durchlaufene Abschnitte wirksam.</li>\n<li>Die E2E-Prüfung erfolgt stets auf der serialisierten Repräsentation (<code>Data</code>), um Konsistenz mit dem senderseitig abgesicherten Datenstrom sicherzustellen.</li>\n</ul>"}, {"id": "FIG-34b918cac16dc110", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des internen Kontrollflusses der E2E-Protection-Wrapper-Funktion <code>E2EPW_Read_&lt;p&gt;_&lt;o&gt;</code> (E2EPW_Read1) innerhalb der AUTOSAR E2E Library. Der Wrapper fungiert als Bindeglied zwischen Software-Komponenten (SWC) und der AUTOSAR-RTE und stellt sicher, dass über die RTE empfangene Daten vor der weiteren Nutzung einer End-to-End-Schutzprüfung (E2E-Check) unterzogen werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Aufrufer:</strong> Software-Komponente (SWC), die Daten über die E2E-Wrapper-Funktion einliest.</li>\n<li><strong>Funktionsparameter / Variablen:</strong></li>\n<li><code>AppDataEl</code>: Zeiger auf den Puffer des Anwendungsdatenelements.</li>\n<li><code>retRteRead</code>: Lokale Variable für den Rückgabewert des RTE-Leseaufrufs.</li>\n<li><code>plausibilityChecks</code>: Statusvariable für Vorprüfungen und Deserialisierungsvalidierung.</li>\n<li><code>retE2ECheck</code>: Lokale Variable für den Rückgabewert der E2E-Prüfroutine.</li>\n<li><code>State</code> / <code>State1</code>: Zustandsstruktur des E2E-Profils (inkl. Flags <code>NewDataAvailable</code> und <code>Status</code>).</li>\n<li><code>Config1</code>: Konfigurationsstruktur für das spezifische E2E-Profil.</li>\n<li><code>Data</code>: Byte-Array bzw. I-PDU-Darstellung des Datenelements.</li>\n<li><code>ret</code>: 32-Bit-Zusammengesetzter Rückgabewert der Wrapper-Funktion.</li>\n<li><strong>Schnittstellen & externe Operationen:</strong></li>\n<li><code>Rte_Read_&lt;p&gt;_&lt;o&gt;(AppDataEl)</code>: RTE-Lese-API für Port <code>&lt;p&gt;</code> und Datenelement <code>&lt;o&gt;</code>.</li>\n<li><code>E2E_PXXCheck(Config1, State1, Data)</code>: Profilspezifische E2E-Prüffunktion der E2E-Library.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Start der Aktivität; Belegung von <code>retRteRead = RTE_E_OK</code>, <code>plausibilityChecks = E2E_E_OK</code> und <code>retE2ECheck = E2E_E_OK</code>.</li>\n<li><strong>Nullzeiger-Prüfung:</strong> Verzweigung über Guard <code>AppDataEl == NULL</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Setzen von <code>plausibilityChecks = E2E_E_INPUTERR_NULL</code>, Umgehung der Lese- und E2E-Prüfschritte zur Zusammenführung vor dem Rückgabewert.</li>\n<li><code>[FALSE]</code>: Ausführung von <code>rteRead = Rte_Read_&lt;p&gt;_&lt;o&gt;(AppDataEl)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Auswertung des RTE-Lesestatus:</strong> Verzweigung über Guard <code>retRteRead == RTE_E_OK</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Setzen von <code>State-&gt;NewDataAvailable = TRUE</code>.</li>\n<li><code>[FALSE]</code>: Setzen von <code>State-&gt;NewDataAvailable = FALSE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deserialisierungsprüfung:</strong> Nach der Zusammenführung erfolgt die Prüfung <code>Check deserialization of AppDataEl</code>. Verzweigung über Guard <code>Deserialization invalid?</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Setzen von <code>plausibilityChecks = E2EPW_E_DESERIALIZATION</code>.</li>\n<li><code>[FALSE]</code>: Serialisierung von <code>AppDataEl</code> in die I-PDU-Repräsentation <code>Data</code> (sofern es sich um ein komplexes Datenelement handelt) bzw. Kopieren in <code>Data</code> (falls Byte-Array). Anschließend Aufruf von <code>retE2ECheck = E2E_PXXCheck(Config1, State1, Data)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ergebnisbildung & Abschluss:</strong> Zusammenführung aller Pfade. Zusammensetzen des 32-Bit-Rückgabewerts per Bitschiebe- und ODER-Operation:</li>\n</ol>\n<p class=\"fig-p\"><code>ret = ( (retRteRead) | (retE2ECheck &lt;&lt; 8) | (plausibilityChecks &lt;&lt; 16) | (State1-&gt;Status &lt;&lt; 24) )</code>.</p>\n<p class=\"fig-p\">Rückgabe von <code>ret</code> und Übergang in den Endzustand.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Der Rückgabewert kodiert vier separate Statusbytes in einem einzigen 32-Bit-Wert: Byte 0 (Bits 0–7) enthält <code>retRteRead</code>, Byte 1 (Bits 8–15) <code>retE2ECheck</code>, Byte 2 (Bits 16–23) <code>plausibilityChecks</code> und Byte 3 (Bits 24–31) <code>State1-&gt;Status</code>.</li>\n<li>Wenn <code>AppDataEl</code> NULL ist oder die Deserialisierung fehlschlägt, wird der eigentliche E2E-Check (<code>E2E_PXXCheck</code>) übersprungen; Vorbelegungen (<code>E2E_E_OK</code>) bleiben für nicht durchlaufene Abschnitte wirksam.</li>\n<li>Die E2E-Prüfung erfolgt stets auf der serialisierten Repräsentation (<code>Data</code>), um Konsistenz mit dem senderseitig abgesicherten Datenstrom sicherzustellen.</li>\n</ul>"}], "trans": [{"from": "FIG-de43d6fa1e379b2a", "to": "FIG-34b918cac16dc110", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
